from collections import defaultdict, deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v==4 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop(); cells.append((x,y))
   for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=nx<R and 0<=ny<C and (nx,ny) not in seen and grid[nx][ny]==v:
     seen.add((nx,ny)); q.append((nx,ny))
  minr=min(x for x,y in cells); minc=min(y for x,y in cells)
  shape=tuple(sorted((x-minr,y-minc) for x,y in cells))
  comps.append((v,(minr,minc),shape,cells))
for i,(v,pos,sh,cells) in enumerate(comps): print(i,v,pos,len(cells),sh)
# exact shape groups
by=defaultdict(list)
for i,co in enumerate(comps): by[co[2]].append(i)
print('duplicates',[(ids,[comps[i][:3] for i in ids]) for ids in by.values() if len(ids)>1])
